import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Testing-for-normality.md","filePath":"manual-zh/Testing-for-normality.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Testing-for-normality.md"};function n(s,t,p,i,l,c){return r(),e("div",null,[...t[0]||(t[0]=[a(`<h4 id="_5-2-5-正态性检验" tabindex="-1">5.2.5 正态性检验 <a class="header-anchor" href="#_5-2-5-正态性检验" aria-label="Permalink to &quot;5.2.5 正态性检验&quot;">​</a></h4><p>许多统计检验依赖于数据的某些特性。许多线性检验所依赖的一个常见特性是正态性——数据必须来自正态分布。因此，在选择要使用的检验方法之前，有必要确认正态性。其中一种方法是使用 <code>EXAMINE</code> 命令。</p><p>在下面的示例中，一位研究者正在检查某工程公司所生产设备的故障率。文件 repairs.sav 包含受研究的部分设备的平均故障间隔时间（<strong>mtbf</strong>）。在对数据进行线性分析之前，研究者想要确认数据是正态分布的。</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/repairs.sav&#39;.
PSPP&gt; examine mtbf
                /statistics=descriptives.
</code></pre><p>这将产生如下输出：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>统计量</th><th>标准误</th></tr></thead><tbody><tr><td>平均故障间隔时间（月）</td><td>均值</td><td>8.78</td><td>1.10</td><td></td></tr><tr><td>均值 95% 置信区间</td><td>下限</td><td>6.53</td><td></td><td></td></tr><tr><td>上限</td><td>11.04</td><td></td><td></td><td></td></tr><tr><td>5% 截尾均值</td><td>8.20</td><td></td><td></td><td></td></tr><tr><td>中位数</td><td>8.29</td><td></td><td></td><td></td></tr><tr><td>方差</td><td>36.34</td><td></td><td></td><td></td></tr><tr><td>标准差</td><td>6.03</td><td></td><td></td><td></td></tr><tr><td>最小值</td><td>1.63</td><td></td><td></td><td></td></tr><tr><td>最大值</td><td>26.47</td><td></td><td></td><td></td></tr><tr><td>全距</td><td>24.84</td><td></td><td></td><td></td></tr><tr><td>四分位距</td><td>6.03</td><td></td><td></td><td></td></tr><tr><td>偏度</td><td>1.65</td><td>.43</td><td></td><td></td></tr><tr><td>峰度</td><td>3.41</td><td>.83</td><td></td><td></td></tr></tbody></table><p>正态分布的偏度与峰度均为零。上面输出中 <strong>mtbf</strong> 的偏度清楚地表明，mtbf 数值具有较大的正偏态，因此并非来自正态分布的变量。正偏态通常可以通过应用对数变换来补偿，如下面该示例的延续部分所示：</p><pre><code>PSPP&gt; compute mtbf_ln = ln (mtbf).
PSPP&gt; examine mtbf_ln
                /statistics=descriptives.
</code></pre><p>这将产生如下附加输出：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>统计量</th><th>标准误</th></tr></thead><tbody><tr><td>mtbf_ln</td><td>均值</td><td>1.95</td><td>.13</td><td></td></tr><tr><td>均值 95% 置信区间</td><td>下限</td><td>1.69</td><td></td><td></td></tr><tr><td>上限</td><td>2.22</td><td></td><td></td><td></td></tr><tr><td>5% 截尾均值</td><td>1.96</td><td></td><td></td><td></td></tr><tr><td>中位数</td><td>2.11</td><td></td><td></td><td></td></tr><tr><td>方差</td><td>.49</td><td></td><td></td><td></td></tr><tr><td>标准差</td><td>.70</td><td></td><td></td><td></td></tr><tr><td>最小值</td><td>.49</td><td></td><td></td><td></td></tr><tr><td>最大值</td><td>3.28</td><td></td><td></td><td></td></tr><tr><td>全距</td><td>2.79</td><td></td><td></td><td></td></tr><tr><td>四分位距</td><td>.88</td><td></td><td></td><td></td></tr><tr><td>偏度</td><td>-.37</td><td>.43</td><td></td><td></td></tr><tr><td>峰度</td><td>.01</td><td>.83</td><td></td><td></td></tr></tbody></table><p>上面第一行的 <code>COMPUTE</code> 命令执行了对数变换：</p><pre><code>compute mtbf_ln = ln (mtbf).
</code></pre><p>这种用法并未重新定义已有变量，而是用 <code>COMPUTE</code> 定义了一个新变量 <strong>mtbf_ln</strong>，它是 <strong>mtbf</strong> 的自然对数。本示例的最后一条命令对这个新变量调用 <code>EXAMINE</code>。结果显示，<strong>mtbf_ln</strong> 的偏度与峰度都非常接近零。这在一定程度上表明 <strong>mtbf_ln</strong> 变量是正态分布的，因此可以安全地用于线性分析。如果找不到合适的变换，那么与其使用线性检验，不如考虑使用适当的非参数检验。关于非参数检验的信息，请见 <a href="./NPAR-TESTS">NPAR TESTS</a>。</p>`,13)])])}const _=d(o,[["render",n]]);export{m as __pageData,_ as default};
